import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdir, writeFile, readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { generate } from '../dist/project.js';
import { compileProject } from '../dist/compiler.js';
import { planInitialize } from '../dist/init.js';
import { temporary } from './helpers.mjs';

async function fixture(t, development) {
  const root = await temporary(t);
  await mkdir(join(root, 'messages'));
  await writeFile(join(root, 'messages/en.json'), JSON.stringify({ greeting: 'Hello {name}', count: '{n, plural, one {# file} other {# files}}' }));
  await writeFile(join(root, 'messages/de.json'), JSON.stringify({ greeting: 'Hallo {name}', count: '{n, plural, one {# Datei} other {# Dateien}}' }));
  return { root, baseLocale: 'en', outDir: 'generated', development };
}

const marker = (development, catalogs) => `// Generated by Nordbeam Locale (${development ? 'development' : 'production'} build). Do not edit: change ${catalogs}/*.json and run \`nordbeam-locale\`.`;

test('generated files name the build mode and the catalog path on their header line', async t => {
  for (const development of [false, true]) {
    const options = await fixture(t, development);
    const result = await generate(options);
    const compiled = compileProject({ baseLocale: 'en', development, catalogs: { en: JSON.parse(await readFile(join(options.root, 'messages/en.json'), 'utf8')), de: JSON.parse(await readFile(join(options.root, 'messages/de.json'), 'utf8')) } });
    const line = marker(development, 'messages');
    for (const name of ['messages.d.ts', 'index.d.ts', 'locales/en.d.ts', 'locales/de.d.ts']) assert.equal(result.files[name].split('\n')[0], line, name);
    assert.equal(result.files['index.js'].split('\n')[0], line, 'index.js');
    assert.equal(result.files['locales/en.js'].split('\n')[0], line, 'locales/en.js');
    assert.equal(result.files['package.json'], compiled.files['package.json'], 'package.json has no header and is unchanged');
    // Only the header line changed: the compiler output and the generated output have the same line structure.
    const withoutMaps = text => text.split('\n').filter(lineText => !lineText.startsWith('//# sourceMappingURL=')).join('\n');
    for (const name of Object.keys(compiled.files).filter(name => name.endsWith('.d.ts'))) {
      assert.equal(withoutMaps(result.files[name]).split('\n').slice(1).join('\n'), withoutMaps(compiled.files[name]).split('\n').slice(1).join('\n'), name);
    }
  }
});

test('loader modules keep the ts-nocheck line ahead of the marked header', async t => {
  const options = { ...(await fixture(t, false)), artifacts: 'loader' };
  const result = await generate(options);
  for (const name of ['index.js', 'internal/locales/en.js']) {
    assert.equal(result.files[name].split('\n')[0], '// @ts-nocheck', name);
    assert.equal(result.files[name].split('\n')[1], marker(false, 'messages'), name);
  }
});

test('a regenerate of marked output is a no-op and writes nothing', async t => {
  const options = await fixture(t, false);
  const first = await generate(options);
  const second = await generate(options);
  assert.deepEqual(second.changed, []);
  assert.deepEqual(second.files, first.files);
});

test('catalog location is relative to the project root, even for a nested generated directory', async t => {
  const options = await fixture(t, false);
  options.catalogs = 'messages';
  options.outDir = 'src/i18n/generated';
  const result = await generate(options);
  assert.equal(result.files['index.d.ts'].split('\n')[0], marker(false, 'messages'));
});

test('an init preview of generated output lists no generated changes', async t => {
  const options = await fixture(t, false);
  options.catalogs = 'messages';
  await generate(options);
  const text = await readFile(join(options.root, 'messages/en.json'), 'utf8');
  const catalogs = { en: JSON.parse(text), de: JSON.parse(await readFile(join(options.root, 'messages/de.json'), 'utf8')) };
  const plan = await planInitialize(options, catalogs, text, join(options.root, 'nordbeam-locale.config.json'), false);
  assert.deepEqual(plan.generated, []);
});
